package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
/** Baseline probe only; no production claim. Map delete uses a distinct UI path. */
final class MapVertexConfirmationChecks {
 final MapAndroidChecks m;final GeometryConfirmationChecks g;final VertexRotationChecks p;final ManagerVisualChecks v;final ManagerRotationChecks r;
 MapVertexConfirmationChecks(MapAndroidChecks m){this.m=m;g=new GeometryConfirmationChecks(m);p=g.p;v=g.v;r=g.r;}
 boolean present(){final boolean[] b={false};m.runOnMainSync(()->{View root=m.activeDialogRoot();b[0]=g.contains(root,"Удалить выбранную вершину из текущего ввода?")&&v.button(root,"Удалить")!=null&&v.button(root,"Отмена")!=null;});return b[0];}
 void snapshot(String stage)throws Exception{JSONObject o=new JSONObject();o.put("stage",stage);o.put("present",present());o.put("key",g.key());o.put("token",m.editorField("expected"));o.put("main",m.geometryInput());o.put("selected",m.call(m.vertexState(),"selected",new Class[]{}));o.put("viewport",Arrays.toString((double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{})));final JSONArray text=new JSONArray();m.runOnMainSync(()->{try{v.inspect(m.activeDialogRoot(),text);}catch(Exception e){throw new RuntimeException(e);}});o.put("texts",text);m.capture("mvisual-map-vertex-confirm-"+stage);v.emit("MAP_VERTEX_CONFIRM_VISUAL "+o.toString());}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());long id=-1;try{id=g.fixture(store,false);Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));g.open(id,false);m.click("Редактировать на карте");m.mapEditorReady();float[] point=m.vertexPixel(1);m.mapTouch(point[0],point[1],point[0],point[1],false,false);m.check((Integer)m.call(m.vertexState(),"selected",new Class[]{})==1,"real map touch selects middle vertex before baseline");String main=m.geometryInput(),token=(String)m.editorField("expected");boolean all=true;for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){m.clickDescription("Удалить выбранную вершину");m.check(present(),"map confirmation fixture");m.click("Отмена");m.check(m.geometryInput().equals(main),"map Cancel before rotation never deletes a vertex");g.unchanged(store,id,xml,assets);m.clickDescription("Удалить выбранную вершину");snapshot("before-"+(direction==UiAutomation.ROTATION_FREEZE_90?"land":"return"));Activity old=m.activity;p.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"map confirmation Activity actually destroyed/recreated");m.mapEditorReady();snapshot("after-"+(direction==UiAutomation.ROTATION_FREEZE_90?"land":"return"));boolean restored=present();all&=restored;m.check(m.geometryInput().equals(main)&&token.equals(m.editorField("expected"))&&g.key().equals("0")&&(Integer)m.call(m.vertexState(),"selected",new Class[]{})==1,"map raw/selected/address/token exact after real rotation");g.unchanged(store,id,xml,assets);if(restored)m.click("Отмена");v.emit("MAP_VERTEX_CONFIRM_BASELINE direction="+direction+" restored="+restored+" raw/selected/token/KML/assets unchanged=true");}m.check(m.requests.get()==requests,"map confirmation baseline uses no online tiles");m.check(all,"map vertex deletion confirmation survives both actual Activity recreations");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);if(id>0)m.call(store,"remove",new Class[]{long.class},id);m.call(store,"close",new Class[]{});}}
}
